await t('coop-stock', 'the same request id with a different quantity is refused', async () => { const r = await rpc('adjust_cooperative_stock', { p_inventory_id: inv.id, p_quantity: 99, p_transaction_type: 'restock', p_request_id: rq1 }, M); return [!ok(r), r.status + ' ' + msg(r)]; });
await t('coop-stock', 'a restock with a negative quantity, an adjustment with a positive one, zero and 3 decimals are all refused', async () => { const bad = [['restock', -1], ['adjustment', 3], ['written_off', 2], ['restock', 0], ['restock', 1.234]]; const out = []; for (const [ty, q] of bad) { const r = await rpc('adjust_cooperative_stock', { p_inventory_id: inv.id, p_quantity: q, p_transaction_type: ty, p_request_id: uid() }, M); out.push(ok(r) ? 'ACCEPTED ' + ty + q : 'x'); } return [out.every(x => x === 'x'), out.join(',')]; });
