await t('coop-stock', 'Manage Officer can write off 0.5 (valid)', async () => { const r = await rpc('adjust_cooperative_stock', { p_inventory_id: inv.id, p_quantity: -0.5, p_transaction_type: 'written_off', p_request_id: uid() }, OM); return [ok(r) && Number(r.json) === 39.5, r.status + ' ' + JSON.stringify(r.json)]; });
await t('coop-stock', 'stock changes are written to the ledger', async () => { const r = await get(`inventory_transactions?select=transaction_type,quantity&inventory_id=eq.${inv.id}&order=created_at`, M); return [rows(r) === 2, JSON.stringify(r.json)]; });
