// ================= C. COOPERATIVE OFFERS (Farmer offers a batch, price negotiation, delivery, receipt) =================
async function makeBatch(F, id, crop, qty, unit = 'kg') {
  const fc = await get(`farmer_crops?select=id,crop_name&farmer_id=eq.${id}&crop_name=eq.${crop}`, F);
  const crop_id = fc.json[0].id;
  const h = await call('POST', '/rest/v1/harvest_records', { token: F, body: { farmer_id: id, crop_id, crop_name: crop, crop_category: 'Vegetables', quantity_kg: qty, harvest_date: new Date().toISOString().slice(0, 10), unit } });
  if (!ok(h)) return { error: msg(h) };
  const b = await call('POST', '/rest/v1/inventory_batches', { token: F, body: { farmer_id: id, harvest_record_id: h.json[0].id, crop_id, crop_name: crop, batch_number: 'x', quantity_kg: qty, available_kg: qty, unit, is_coop_eligible: true } });
  return { batch: ok(b) ? b.json[0] : null, error: ok(b) ? null : msg(b) };
}
