await t('offers', 'delivery needs a photo; Farmer 1 delivers; the Manager confirms receipt twice, yet the stock and the payment amount are applied exactly once (10 kg x ₱35 = ₱350)', async () => {
  const noPhoto = await rpc('deliver_cooperative_offer', { p_offer_id: off.id, p_photo_url: '', p_note: null }, F1);
  const d = await rpc('deliver_cooperative_offer', { p_offer_id: off.id, p_photo_url: 'https://example.invalid/proof.jpg', p_note: 'on time' }, F1);
  const c = await rpc('confirm_cooperative_offer_receipt', { p_offer_id: off.id, p_note: 'received' }, M);
  const again = await rpc('confirm_cooperative_offer_receipt', { p_offer_id: off.id, p_note: 'again' }, M);
  const o2 = (await get('cooperative_purchase_offers?select=*&id=eq.' + off.id, M)).json?.[0];
  const tx = await get('inventory_transactions?select=quantity&reference_id=eq.' + off.id + '&transaction_type=eq.harvest_received', M);
  const stock = Number((await get('cooperative_inventory?select=quantity_on_hand&id=eq.' + o2?.coop_inventory_id, M)).json?.[0]?.quantity_on_hand);
  const led = await get('inventory_transactions?select=quantity&inventory_id=eq.' + o2?.coop_inventory_id, M); const ledgerSum = (led.json || []).reduce((a, x) => a + Number(x.quantity), 0);
  const good = !ok(noPhoto) && ok(d) && ok(c) && rows(tx) === 1 && Number(tx.json[0].quantity) === 10 && Number(o2.confirmed_amount) === 350 && stock === ledgerSum;
  return [good, 'photo-less ' + noPhoto.status + ', deliver ' + d.status + ', confirm ' + c.status + ', again ' + again.status + ', receipts=' + rows(tx) + ', amount=' + o2?.confirmed_amount + ', stock=' + stock + ' (ledger sum ' + ledgerSum + ')' + ', status=' + o2?.status];
});
