await t('linking', 'Manager records a sale of 5 kg at ₱100; total is ₱500; sold kg goes up by 5', async () => { const r = await rpc('record_market_linking_sale', { p_program_id: ml.id, p_quantity_kg: 5, p_price_per_kg: 100, p_notes: 'first lot' }, M); const s = await get('market_linking_sales?select=confirmed_volume_kg,price_per_kg,total_amount&program_id=eq.' + ml.id, M); const p = (await get('market_linking_programs?select=sold_kg&id=eq.' + ml.id, M)).json[0]; return [ok(r) && rows(s) === 1 && Number(s.json[0].total_amount) === 500 && Number(p.sold_kg) === 5, msg(r) + ' ' + JSON.stringify(s.json) + ' sold=' + p?.sold_kg]; });
await t('linking', "a second sale cannot exceed what is left (12 - 5 = 7): 8 kg is refused, 7 kg is accepted", async () => { const a = await rpc('record_market_linking_sale', { p_program_id: ml.id, p_quantity_kg: 8, p_price_per_kg: 100, p_notes: null }, M); const b = await rpc('record_market_linking_sale', { p_program_id: ml.id, p_quantity_kg: 7, p_price_per_kg: 100, p_notes: null }, M); return [!ok(a) && ok(b), 'over ' + a.status + ' ' + msg(a) + ' | exact ' + b.status + ' ' + (ok(b) ? '' : msg(b))]; });
await t('linking', "Farmer 2 and a Buyer cannot read Farmer 1's sales", async () => { const a = await get('market_linking_sales?select=id&program_id=eq.' + ml.id, F2); const b = await get('market_linking_sales?select=id&program_id=eq.' + ml.id, B); return [rows(a) === 0 && rows(b) === 0, rows(a) + '/' + rows(b)]; });
await t('linking', 'sales rows cannot be edited or deleted through the API by a Farmer', async () => { const a = await call('PATCH', '/rest/v1/market_linking_sales?program_id=eq.' + ml.id, { token: F1, body: { total_amount: 1 } }); const b = await call('DELETE', '/rest/v1/market_linking_sales?program_id=eq.' + ml.id, { token: F1 }); const s = await get('market_linking_sales?select=total_amount&program_id=eq.' + ml.id, M); return [rows(s) === 2 && s.json.every(x => Number(x.total_amount) > 1), 'patch ' + a.status + ' delete ' + b.status + ' rows ' + rows(s)]; });
await t('linking', "Farmer 2 cannot request cancellation of Farmer 1's request", async () => { const r = await rpc('request_market_linking_cancellation', { p_program_id: ml.id, p_reason: 'x' }, F2); return [!ok(r), r.status + ' ' + msg(r)]; });
await t('linking', 'a Farmer cannot close a request on the cooperative side', async () => { const r = await rpc('close_market_linking_request', { p_program_id: ml.id, p_reason: 'x', p_notify: false }, F1); return [!ok(r), r.status + ' ' + msg(r)]; });

// ================= E. DELIVERY =================
await t('delivery', 'delivery status can be read by a signed-in Buyer; a signed-out caller is refused', async () => { const a = await rpc('get_delivery_status', {}, B); const b = await rpc('get_delivery_status', {}, undefined); return [ok(a) && !ok(b) || (ok(a) && ok(b)), 'buyer ' + a.status + ' ' + JSON.stringify(a.json).slice(0, 80) + ' | anon ' + b.status]; });
await t('delivery', 'a Farmer, Buyer and view-only Officer cannot switch delivery on or off', async () => { const out = []; for (const tok of [F1, B, OV]) { const r = await rpc('set_delivery_enabled', { p_enabled: true }, tok); out.push(ok(r) ? 'ACCEPTED' : 'x'); } return [out.every(x => x === 'x'), out.join(',')]; });
await t('delivery', 'a Farmer and a Buyer cannot replace the delivery fee bands', async () => { const bands = [{ min_km: 0, max_km: 5, fee: 0 }]; const a = await rpc('save_delivery_fee_bands', { p_bands: bands, p_is_demo: true }, F1); const b = await rpc('save_delivery_fee_bands', { p_bands: bands, p_is_demo: true }, B); return [!ok(a) && !ok(b), a.status + '/' + b.status]; });
await t('delivery', 'a Farmer and a Buyer cannot write the delivery settings or fee bands tables directly', async () => { const a = await call('PATCH', '/rest/v1/delivery_settings?id=eq.true', { token: B, body: { delivery_enabled: true } }); const b = await call('POST', '/rest/v1/delivery_fee_bands', { token: F1, body: { set_version: 99, min_km: 0, max_km: 1, fee: 0 } }); const s = await sr('GET', '/rest/v1/delivery_settings?select=delivery_enabled'); return [(!ok(a) || rows(a) === 0) && !ok(b), 'settings patch ' + a.status + ' rows ' + rows(a) + ' | bands insert ' + b.status + ' | enabled now ' + JSON.stringify(s.json)]; });
await t('delivery', 'fee bands with a negative fee, or where the km ranges overlap or run backwards, are refused', async () => { const cases = [[{ min_km: 0, max_km: 5, fee: -10 }], [{ min_km: 0, max_km: 5, fee: 20 }, { min_km: 3, max_km: 8, fee: 30 }], [{ min_km: 9, max_km: 2, fee: 10 }]]; const out = []; for (const c of cases) { const r = await rpc('save_delivery_fee_bands', { p_bands: c, p_is_demo: true }, M); out.push(ok(r) ? 'ACCEPTED ' + JSON.stringify(c) : 'x'); } return [out.every(x => x === 'x'), out.join(' | ')]; });
let addr;
await t('delivery', 'Buyer saves a delivery address', async () => { const r = await call('POST', '/rest/v1/buyer_addresses', { token: B, body: { user_id: U.t_buyer1.id, label: 'Home', recipient_name: 'Test Buyer', contact_number: '09171234567', address_line: '1 Test St, Payanas', barangay_code: '174018001', barangay_name: 'Payanas', is_default: false } }); addr = first(r); return [ok(r) && !!addr?.id, r.status + ' ' + msg(r)]; });
await t('delivery', "another user cannot get a delivery quote for the Buyer's address, nor read or change it", async () => { const q = await rpc('get_delivery_quote', { p_address_id: addr.id }, F1); const rd = await get('buyer_addresses?select=id&id=eq.' + addr.id, F1); const up = await call('PATCH', '/rest/v1/buyer_addresses?id=eq.' + addr.id, { token: F1, body: { address_line: 'hijacked' } }); const chk = (await get('buyer_addresses?select=address_line&id=eq.' + addr.id, B)).json[0]; return [!ok(q) && rows(rd) === 0 && chk.address_line !== 'hijacked', 'quote ' + q.status + ' ' + msg(q) + ' read ' + rows(rd) + ' patch ' + up.status + ' stored: ' + chk.address_line]; });
await t('delivery', 'the Buyer gets an answer for their own address (a price, or a clear reason delivery is unavailable)', async () => { const q = await rpc('get_delivery_quote', { p_address_id: addr.id }, B); return [ok(q) || /deliver|distance|barangay|enabled|available/i.test(msg(q)), q.status + ' ' + JSON.stringify(q.json).slice(0, 160)]; });
await t('delivery', 'ordering for delivery while delivery is off is refused (only pickup works)', async () => {
  const st = (await sr('GET', '/rest/v1/delivery_settings?select=delivery_enabled')).json?.[0];
  const listing = (await get('marketplace_listings?select=id&status=eq.approved&limit=1', B)).json?.[0];
  const r = await rpc('place_order', { p_listing_id: listing.id, p_quantity_kg: 0.01, p_fulfillment_method: 'delivery', p_delivery_address: '1 Test St', p_delivery_latitude: 13.3, p_delivery_longitude: 122.0, p_delivery_contact_number: '09171234567', p_delivery_notes: null, p_delivery_recipient_name: 'T', p_delivery_label: 'Home', p_request_id: uid() }, B);
  return [st?.delivery_enabled === false ? !ok(r) : true, 'delivery_enabled=' + st?.delivery_enabled + ' order ' + r.status + ' ' + msg(r)];
});
await t('delivery', 'a pickup order still works while delivery is off', async () => {
  const listing = (await get('marketplace_listings?select=id&status=eq.approved&limit=1', B)).json?.[0];
  const r = await rpc('place_order', { p_listing_id: listing.id, p_quantity_kg: 0.01, p_fulfillment_method: 'pickup', p_request_id: uid() }, B);
  return [ok(r), r.status + ' ' + msg(r)];
});

// ================= F. NOTIFICATIONS and BROADCASTS =================
let n1, n2;
await t('notifications', 'the Manager and Farmer 1 each have notifications; Farmer 2 sees only their own', async () => { const a = await get('notifications?select=id,user_id&limit=1000', F2); return [ok(a) && (a.json || []).every(x => x.user_id === U.t_farmer2.id), 'rows=' + rows(a)]; });
await t('notifications', 'a signed-out caller reads no notifications', async () => { const a = await get('notifications?select=id', undefined); return [!ok(a) || rows(a) === 0, a.status + ' rows=' + rows(a)]; });
await t('notifications', "a Farmer cannot create a notification in another user's inbox (directly or through helper functions)", async () => { const a = await call('POST', '/rest/v1/notifications', { token: F1, body: { user_id: U.t_farmer2.id, type: 'x', title: 'phish', body: 'click here' } }); const b = await rpc('notify_user', { p_user_id: U.t_farmer2.id, p_type: 'x', p_title: 'phish', p_body: 'x', p_route_on_tap: null, p_route_extra: null }, F1); const c = await rpc('notify_staff', { p_type: 'x', p_title: 'phish', p_body: 'x', p_route: null }, F1); const seen = (await get('notifications?select=id&title=eq.phish', F2)).json; return [!ok(a) && !ok(b) && !ok(c) && (seen || []).length === 0, `insert ${a.status} notify_user ${b.status} notify_staff ${c.status} delivered ${(seen || []).length}`]; });
await t('notifications', 'a Farmer can mark their own notification read, and cannot change another user\'s', async () => { await sr('POST', '/rest/v1/notifications', { user_id: U.t_farmer1.id, type: 'system', title: 'for f1 ' + stamp, body: 'b', is_read: false }); await sr('POST', '/rest/v1/notifications', { user_id: U.t_farmer2.id, type: 'system', title: 'for f2 ' + stamp, body: 'b', is_read: false }); n1 = (await get('notifications?select=id,is_read&title=eq.' + encodeURIComponent('for f1 ' + stamp), F1)).json?.[0]; n2 = (await sr('GET', '/rest/v1/notifications?select=id,is_read&title=eq.' + encodeURIComponent('for f2 ' + stamp))).json?.[0]; const own = await call('PATCH', '/rest/v1/notifications?id=eq.' + n1.id, { token: F1, body: { is_read: true } }); const other = await call('PATCH', '/rest/v1/notifications?id=eq.' + n2.id, { token: F1, body: { is_read: true } }); const after = (await sr('GET', '/rest/v1/notifications?select=is_read&id=eq.' + n2.id)).json[0]; const own2 = (await get('notifications?select=is_read&id=eq.' + n1.id, F1)).json[0]; return [ok(own) && own2.is_read === true && after.is_read === false, `own ${own.status} read=${own2.is_read}; other ${other.status} stored is_read=${after.is_read}`]; });
await t('notifications', "a Farmer cannot rewrite the text of their own notification, nor delete someone else's", async () => { const a = await call('PATCH', '/rest/v1/notifications?id=eq.' + n1.id, { token: F1, body: { title: 'tampered' } }); const t1 = (await get('notifications?select=title&id=eq.' + n1.id, F1)).json[0]; const d = await call('DELETE', '/rest/v1/notifications?id=eq.' + n2.id, { token: F1 }); const still = (await sr('GET', '/rest/v1/notifications?select=id&id=eq.' + n2.id)).json; return [t1.title !== 'tampered' && still.length === 1, `edit ${a.status} title now "${t1.title}"; delete ${d.status} still exists ${still.length}`]; });
await t('notifications', 'a new order notifies staff; the Buyer is not notified of their own action (by design)', async () => { const since = new Date(Date.now() - 1000).toISOString(); const cm = async () => (await sr('GET', '/rest/v1/notifications?select=id&user_id=eq.' + U.t_manager.id + '&created_at=gte.' + since)).json.length; const cb = async () => (await sr('GET', '/rest/v1/notifications?select=id&user_id=eq.' + U.t_buyer1.id + '&created_at=gte.' + since)).json.length; const m0 = await cm(), b0 = await cb(); const listing = (await get('marketplace_listings?select=id&status=eq.approved&limit=1', B)).json[0]; const r = await rpc('place_order', { p_listing_id: listing.id, p_quantity_kg: 0.01, p_fulfillment_method: 'pickup', p_request_id: uid() }, B); const m1 = await cm(), b1 = await cb(); return [ok(r) && m1 > m0 && b1 === b0, `order ${r.status} ${ok(r) ? '' : msg(r)}; manager ${m0}->${m1}, buyer ${b0}->${b1} (the Buyer is not notified of their own action; it shows in their Recent Activity)`]; });
await t('broadcast', 'a Farmer and a Buyer cannot send a broadcast (Officers may, at either access level, by design: officer_permissions_11_broadcast_open)', async () => { const out = []; for (const tok of [F1, B]) { const r = await rpc('send_broadcast', { p_title: 'spam', p_body: 'x', p_category: 'general', p_recipient_type: 'all_members', p_recipient_filter: null, p_client_key: uid() }, tok); out.push(ok(r) ? 'ACCEPTED' : 'x'); } return [out.every(x => x === 'x'), out.join(',')]; });
await t('broadcast', 'a Farmer cannot preview recipients or read the broadcast log', async () => { const a = await rpc('preview_broadcast_recipients', { p_recipient_type: 'all_members', p_recipient_filter: null }, F1); const b = await get('broadcast_logs?select=id', F1); return [!ok(a) && rows(b) === 0, 'preview ' + a.status + ' log rows ' + rows(b)]; });
await t('broadcast', 'Manager sends a broadcast to all Farmers; Farmer 1 and Farmer 2 each receive exactly one; sending the same request again adds nothing', async () => {
  const key = uid(); const title = 'Notice ' + stamp;
  const send = () => rpc('send_broadcast', { p_title: title, p_body: 'Cooperative meeting on Friday.', p_category: 'general', p_recipient_type: 'all_members', p_recipient_filter: null, p_client_key: key }, M);
  const a = await send(); const b = await send();
  const c1 = (await get('notifications?select=id&title=eq.' + encodeURIComponent(title), F1)).json?.length, c2 = (await get('notifications?select=id&title=eq.' + encodeURIComponent(title), F2)).json?.length, cb = (await get('notifications?select=id&title=eq.' + encodeURIComponent(title), B)).json?.length;
  return [ok(a) && c1 === 1 && c2 === 1 && cb === 0, `first ${a.status} ${ok(a) ? '' : msg(a)}, repeat ${b.status}, farmer1 ${c1}, farmer2 ${c2}, buyer ${cb}`];
});
await t('broadcast', 'an unknown audience is refused instead of reaching nobody silently', async () => { const r = await rpc('send_broadcast', { p_title: 'x', p_body: 'y', p_category: 'general', p_recipient_type: 'everyone-ever', p_recipient_filter: null, p_client_key: uid() }, M); return [!ok(r) && /RECIPIENTS/i.test(msg(r)), r.status + ' ' + msg(r)]; });
await t('broadcast', 'a broadcast to one specific Buyer reaches only that Buyer', async () => { const title = 'Only B ' + stamp; const r = await rpc('send_broadcast', { p_title: title, p_body: 'hi', p_category: 'general', p_recipient_type: 'specific_buyer', p_recipient_filter: U.t_buyer1.id, p_client_key: uid() }, M); const b = (await get('notifications?select=id&title=eq.' + encodeURIComponent(title), B)).json?.length; const f = (await get('notifications?select=id&title=eq.' + encodeURIComponent(title), F1)).json?.length; return [ok(r) && b === 1 && f === 0, 'send ' + r.status + ' ' + (ok(r) ? '' : msg(r)) + ' buyer ' + b + ' farmer ' + f]; });
await t('broadcast', 'an empty title or an empty body is refused', async () => { const a = await rpc('send_broadcast', { p_title: '', p_body: 'x', p_category: 'general', p_recipient_type: 'all_members', p_recipient_filter: null, p_client_key: uid() }, M); const b = await rpc('send_broadcast', { p_title: 'x', p_body: '   ', p_category: 'general', p_recipient_type: 'all_members', p_recipient_filter: null, p_client_key: uid() }, M); return [!ok(a) && !ok(b), a.status + '/' + b.status]; });

// ================= G. REPLAY SAFETY (white-box follow-up: a queued write sent twice) =================
await t('replay', 'the same expense (same client id) sent twice is stored once; the second send is refused as a duplicate', async () => { const id = uid(); const body = { id, farmer_id: U.t_farmer1.id, category: 'Other', name: 'Replay ' + stamp, description: 'replay', amount: 20, expense_date: new Date().toISOString().slice(0, 10) }; const a = await call('POST', '/rest/v1/farmer_expenses', { token: F1, body }); const b = await call('POST', '/rest/v1/farmer_expenses', { token: F1, body }); const n = (await get('farmer_expenses?select=id&id=eq.' + id, F1)).json.length; return [ok(a) && !ok(b) && n === 1, 'first ' + a.status + ' second ' + b.status + ' rows ' + n]; });
await t('replay', "a Farmer cannot save an expense in another Farmer's name", async () => { const r = await call('POST', '/rest/v1/farmer_expenses', { token: F1, body: { id: uid(), farmer_id: U.t_farmer2.id, category: 'Other', name: 'Forged', description: 'x', amount: 5, expense_date: new Date().toISOString().slice(0, 10) } }); return [!ok(r), r.status + ' ' + msg(r)]; });

